/**
 * SQL table shapes (MySQL + PostgreSQL) for Kysely. Conventions (database-safety rule):
 * - money in integer paise (`integer`), never float;
 * - times as `datetime(3)` (MySQL, UTC session) / `timestamptz(3)` (PostgreSQL), read back as Date;
 * - ids are opaque strings generated by the app (`cus_…`), so the same ids work on MongoDB;
 * - flexible, non-queried data in JSON columns only.
 */
export interface ConsentRecordsTable {
  id: string;
  user_id: string | null;
  visitor_id: string | null;
  subscriber_id: string | null;
  purpose: string;
  status: string;
  method: string;
  source: string;
  notice_version: string;
  ip_address: string;
  user_agent: string;
  created_at: Date;
}

export interface CustomersTable {
  id: string;
  phone: string;
  name: string | null;
  email: string | null;
  created_at: Date;
  order_count: number;
  /** JSON object: coupon code → uses. */
  coupon_uses: string | Record<string, number>;
  cod_blocked: boolean | number;
  rto_count: number;
  erased_at: Date | null;
}

export interface CustomerAddressesTable {
  id: string;
  customer_id: string;
  position: number;
  name: string;
  phone: string;
  pincode: string;
  line1: string;
  line2: string;
  landmark: string;
  city: string;
  state: string;
  type: string;
}

export interface SessionsTable {
  token_hash: string;
  customer_id: string;
  created_at: Date;
  expires_at: Date;
}

export interface OtpChallengesTable {
  id: string;
  phone: string;
  code_hash: string;
  expires_at: Date;
  attempts: number;
  used: boolean | number;
}

export interface OtpSendsTable {
  id: string;
  phone: string;
  sent_at: Date;
}

export interface AppLocksTable {
  lock_key: string;
  owner: string;
  expires_at: Date;
}
export interface MarkersTable {
  namespace: string;
  marker_key: string;
  created_at: Date;
}
export interface CountersTable {
  name: string;
  value: number | string;
}
export interface CartsTable {
  id: string;
  doc: unknown;
  version: number;
  updated_at: Date;
}
export interface OrdersTable {
  number: string;
  id: string;
  customer_id: string;
  status: string;
  idempotency_key: string;
  created_at: Date;
  doc: unknown;
  version: number;
}
export interface OrderPaymentsTable {
  payment_id: string;
  order_number: string;
}
export interface InventorySkusTable {
  product_id: string;
  size: string;
  on_hand: number;
}
export interface InventoryReservationsTable {
  reference: string;
  state: string;
  expires_at: Date;
}
export interface InventoryReservationItemsTable {
  reference: string;
  product_id: string;
  size: string;
  quantity: number;
}
export interface LedgerOwnersTable {
  ledger: string;
  owner: string;
  balance: number | string;
}
export interface LedgerEntriesTable {
  id: string;
  ledger: string;
  owner: string;
  amount: number | string;
  reference: string;
  meta: unknown;
  created_at: Date;
}
export interface LoyaltyMembersTable {
  customer_id: string;
  joined_at: Date;
  referral_code: string;
  visitor_id: string | null;
}
export interface LoyaltyReferralsTable {
  order_number: string;
  code: string;
  referrer_id: string;
  friend_id: string;
  created_at: Date;
}
export interface GiftCardsTable {
  hash: string;
  last4: string;
  initial: number;
  issued_at: Date;
  expires_at: Date;
  issued_by: string;
  note: string;
  disabled: boolean | number;
}

export interface Database {
  app_locks: AppLocksTable;
  markers: MarkersTable;
  counters: CountersTable;
  carts: CartsTable;
  orders: OrdersTable;
  order_payments: OrderPaymentsTable;
  inventory_skus: InventorySkusTable;
  inventory_reservations: InventoryReservationsTable;
  inventory_reservation_items: InventoryReservationItemsTable;
  ledger_owners: LedgerOwnersTable;
  ledger_entries: LedgerEntriesTable;
  loyalty_members: LoyaltyMembersTable;
  loyalty_referrals: LoyaltyReferralsTable;
  gift_cards: GiftCardsTable;
  consent_records: ConsentRecordsTable;
  customers: CustomersTable;
  customer_addresses: CustomerAddressesTable;
  sessions: SessionsTable;
  otp_challenges: OtpChallengesTable;
  otp_sends: OtpSendsTable;
}
